1	import { accountScope, registerAccountMigrationValidator, type AccountScope } from "@repo/plugin-web-storage";
2	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
3	import { DEFAULT_TIME_TRACKER_CATEGORIES } from "./defaults.js";
4	import { entryDuration, entriesInWindow, isRunningEntry, startOfDay, startOfWeek } from "./time.js";
5	import type {
6	  LocalizedText,
7	  TimeTrackerCategory,
8	  TimeTrackerEntry,
9	  TimeTrackerMode,
10	  TimeTrackerSnapshot,
11	  TimeTrackerSubcategory,
12	} from "../types.js";
13	
14	export const TIME_TRACKER_CATEGORIES_KEY = "xai_tt_categories_v2";
15	export const TIME_TRACKER_ENTRIES_KEY = "xai_tt_entries_v2";
16	export const TIME_TRACKER_MODE_KEY = "xai_tt_mode";
17	export const TIME_TRACKER_STORAGE_EVENT = "xai:time-tracker-storage";
18	
19	function isRecord(value: unknown): value is Record<string, unknown> {
20	  return typeof value === "object" && value !== null;
21	}
22	
23	function isLocalizedText(value: unknown): value is LocalizedText {
24	  return isRecord(value) && typeof value["en"] === "string" && typeof value["zh"] === "string";
25	}
26	
27	function isSubcategory(value: unknown): value is TimeTrackerSubcategory {
28	  return (
29	    isRecord(value) &&
30	    typeof value["id"] === "string" &&
31	    isLocalizedText(value["name"]) &&
32	    (value["color"] === undefined || typeof value["color"] === "string") &&
33	    (value["icon"] === undefined || typeof value["icon"] === "string")
34	  );
35	}
36	
37	function isCategory(value: unknown): value is TimeTrackerCategory {
38	  return (
39	    isRecord(value) &&
40	    typeof value["id"] === "string" &&
41	    isLocalizedText(value["name"]) &&
42	    typeof value["color"] === "string" &&
43	    typeof value["icon"] === "string" &&
44	    typeof value["goalMin"] === "number" &&
45	    Array.isArray(value["subs"]) &&
46	    value["subs"].every(isSubcategory) &&
47	    typeof value["createdAt"] === "number" &&
48	    typeof value["updatedAt"] === "number"
49	  );
50	}
51	
52	function isSegment(value: unknown): boolean {
53	  return (
54	    isRecord(value) &&
55	    typeof value["start"] === "number" &&
56	    (typeof value["end"] === "number" || value["end"] === null)
57	  );
58	}
59	
60	function isEntry(value: unknown): value is TimeTrackerEntry {
61	  return (
62	    isRecord(value) &&
63	    typeof value["id"] === "string" &&
64	    typeof value["categoryId"] === "string" &&
65	    (typeof value["subId"] === "string" || value["subId"] === null) &&
66	    Array.isArray(value["segments"]) &&
67	    value["segments"].length > 0 &&
68	    value["segments"].every(isSegment) &&
69	    isLocalizedText(value["note"]) &&
70	    typeof value["done"] === "boolean" &&
71	    typeof value["createdAt"] === "number" &&
72	    typeof value["updatedAt"] === "number"
73	  );
74	}
75	
76	function normalizeCategory(category: TimeTrackerCategory): TimeTrackerCategory {
77	  const defaultCategory = DEFAULT_TIME_TRACKER_CATEGORIES.find((item) => item.id === category.id);
78	  return {
79	    ...category,
80	    subs: category.subs.map((sub) => {
81	      const defaultSub = defaultCategory?.subs.find((item) => item.id === sub.id);
82	      return {
83	        ...sub,
84	        color: sub.color ?? defaultSub?.color ?? category.color,
85	        icon: sub.icon ?? defaultSub?.icon ?? category.icon,
86	      };
87	    }),
88	  };
89	}
90	
91	function safeParse(raw: string | null): unknown {
92	  if (raw === null) return null;
93	  try {
94	    return JSON.parse(raw) as unknown;
95	  } catch {
96	    return null;
97	  }
98	}
99	
100	function readJson(key: string, scope = accountScope.capture()): unknown {
101	  if (typeof window === "undefined") return null;
102	  return safeParse(window.localStorage.getItem(accountScope.physicalKey(key, scope)));
103	}
104	
105	function writeJson<T>(key: string, value: T, scope = accountScope.capture()): void {
106	  if (typeof window === "undefined") return;
107	  window.localStorage.setItem(accountScope.physicalKey(key, scope), JSON.stringify(value));
108	  window.dispatchEvent(new CustomEvent(TIME_TRACKER_STORAGE_EVENT, { detail: { key } }));
109	}
110	
111	export function readTimeTrackerCategories(scope = accountScope.capture()): TimeTrackerCategory[] {
112	  const raw = readJson(TIME_TRACKER_CATEGORIES_KEY, scope);
113	  if (!Array.isArray(raw)) return [...DEFAULT_TIME_TRACKER_CATEGORIES];
114	  const categories = raw.filter(isCategory).filter((category) => category.deleted !== true).map(normalizeCategory);
115	  return categories.length > 0 ? categories : [...DEFAULT_TIME_TRACKER_CATEGORIES];
116	}
117	
118	export function readTimeTrackerEntries(scope = accountScope.capture()): TimeTrackerEntry[] {
119	  const raw = readJson(TIME_TRACKER_ENTRIES_KEY, scope);
120	  if (!Array.isArray(raw)) return [];
121	  return raw.filter(isEntry).filter((entry) => entry.deleted !== true);
122	}
123	
124	export function readTimeTrackerMode(): TimeTrackerMode {
125	  if (typeof window === "undefined") return "single";
126	  return window.localStorage.getItem(TIME_TRACKER_MODE_KEY) === "multi" ? "multi" : "single";
127	}
128	
129	export function writeTimeTrackerCategories(categories: readonly TimeTrackerCategory[], scope = accountScope.capture()): void {
130	  writeJson(TIME_TRACKER_CATEGORIES_KEY, categories, scope);
131	}
132	
133	export function writeTimeTrackerEntries(entries: readonly TimeTrackerEntry[], scope = accountScope.capture()): void {
134	  writeJson(TIME_TRACKER_ENTRIES_KEY, entries, scope);
135	}
136	
137	export function writeTimeTrackerMode(mode: TimeTrackerMode): void {
138	  if (typeof window === "undefined") return;
139	  window.localStorage.setItem(TIME_TRACKER_MODE_KEY, mode);
140	  window.dispatchEvent(new CustomEvent(TIME_TRACKER_STORAGE_EVENT, { detail: { key: TIME_TRACKER_MODE_KEY } }));
141	}
142	
143	export function createTimeTrackerEntry(
144	  categoryId: string,
145	  subId: string | null,
146	  startMs: number,
147	  endMs: number | null,
148	  note: LocalizedText,
149	): TimeTrackerEntry {
150	  const stamp = Date.now();
151	  return {
152	    id: `tt_${stamp.toString(36)}_${Math.random().toString(36).slice(2, 8)}`,
153	    categoryId,
154	    subId,
155	    segments: [{ start: startMs, end: endMs }],
156	    note,
157	    done: endMs !== null,
158	    createdAt: stamp,
159	    updatedAt: stamp,
160	  };
161	}
162	
163	/** Terminal commands are replay-safe. Close every open segment, including legacy
164	 * malformed rows; retain the original source separately before repository repair. */
165	export function finishTimeTrackerEntry(entry: TimeTrackerEntry, atMs: number): TimeTrackerEntry {
166	  if (entry.deleted || !Number.isFinite(atMs)) return entry;
167	  const open = entry.segments.filter(segment => segment.end === null);
168	  if (open.some(segment => atMs < segment.start)) return entry;
169	  if (entry.done && open.length === 0) return entry;
170	  return { ...entry, segments: entry.segments.map(segment => segment.end === null ? { ...segment, end: atMs } : segment), done: true, updatedAt: atMs };
171	}
172	
173	export function pauseTimeTrackerEntry(entry: TimeTrackerEntry, atMs: number): TimeTrackerEntry {
174	  if (entry.deleted || entry.done || !Number.isFinite(atMs)) return entry;
175	  const open = entry.segments.filter(segment => segment.end === null);
176	  if (open.length === 0 || open.some(segment => atMs < segment.start)) return entry;
177	  return { ...entry, segments: entry.segments.map(segment => segment.end === null ? { ...segment, end: atMs } : segment), updatedAt: atMs };
178	}
179	
180	export function resumeTimeTrackerEntry(entry: TimeTrackerEntry, atMs: number): TimeTrackerEntry {
181	  if (entry.deleted || entry.done || !Number.isFinite(atMs) || entry.segments.some(segment => segment.end === null)) return entry;
182	  const last = entry.segments.at(-1);
183	  if (!last || last.end === null || atMs < last.end) return entry;
184	  return { ...entry, segments: [...entry.segments, { start: atMs, end: null }], updatedAt: atMs };
185	}
186	
187	export function deleteTimeTrackerEntry(entry: TimeTrackerEntry, atMs: number): TimeTrackerEntry {
188	  return { ...entry, deleted: true, updatedAt: atMs };
189	}
190	
191	export function getTimeTrackerSnapshot(nowMs = Date.now()): TimeTrackerSnapshot {
192	  const categories = readTimeTrackerCategories();
193	  const entries = readTimeTrackerEntries();
194	  const todayStart = startOfDay(nowMs);
195	  const weekStart = startOfWeek(nowMs);
196	  const todayEntries = entriesInWindow(entries, todayStart, nowMs, nowMs);
197	  const weekEntries = entriesInWindow(entries, weekStart, nowMs, nowMs);
198	  const activeEntries = entries.filter(isRunningEntry);
199	  const byCategory = new Map<string, number>();
200	  for (const entry of todayEntries) {
201	    byCategory.set(entry.categoryId, (byCategory.get(entry.categoryId) ?? 0) + entryDuration(entry, nowMs));
202	  }
203	  const topCategoryId = Array.from(byCategory.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;
204	  const topCategory = topCategoryId === null ? null : categories.find((category) => category.id === topCategoryId) ?? null;
205	  return {
206	    todayTotalMs: todayEntries.reduce((total, entry) => total + entryDuration(entry, nowMs), 0),
207	    weekTotalMs: weekEntries.reduce((total, entry) => total + entryDuration(entry, nowMs), 0),
208	    runningCount: activeEntries.length,
209	    activeTotalMs: activeEntries.reduce((total, entry) => total + entryDuration(entry, nowMs), 0),
210	    entriesToday: todayEntries.length,
211	    topCategoryName: topCategory?.name ?? null,
212	  };
213	}
214	
215	export function useTimeTrackerStorage<T>(read: (scope?: AccountScope) => T, write: (value: T, scope?: AccountScope) => void): readonly [T, (next: T | ((prev: T) => T)) => void] {
216	  const scope = useRef(accountScope.capture()).current;
217	  const [value, setValue] = useState<T>(() => read(scope));
218	  const valueRef = useRef(value);
219	
220	  useEffect(() => {
221	    valueRef.current = value;
222	  }, [value]);
223	
224	  useEffect(() => {
225	    function refresh(): void {
226	      if (!accountScope.isReady(scope)) return;
227	      const nextValue = read(scope);
228	      valueRef.current = nextValue;
229	      setValue(nextValue);
230	    }
231	    window.addEventListener("storage", refresh);
232	    window.addEventListener(TIME_TRACKER_STORAGE_EVENT, refresh);
233	    return () => {
234	      window.removeEventListener("storage", refresh);
235	      window.removeEventListener(TIME_TRACKER_STORAGE_EVENT, refresh);
236	    };
237	  }, [read, scope]);
238	
239	  const setStored = useCallback(
240	    (next: T | ((prev: T) => T)) => {
241	      if (!accountScope.isReady(scope)) return;
242	      const nextValue = typeof next === "function" ? (next as (prev: T) => T)(valueRef.current) : next;
243	      valueRef.current = nextValue;
244	      write(nextValue, scope);
245	      setValue(nextValue);
246	    },
247	    [write, scope],
248	  );
249	
250	  return [value, setStored] as const;
251	}
252	
253	export function useTimeTrackerCategories(): readonly [TimeTrackerCategory[], (next: TimeTrackerCategory[] | ((prev: TimeTrackerCategory[]) => TimeTrackerCategory[])) => void] {
254	  return useTimeTrackerStorage(readTimeTrackerCategories, writeTimeTrackerCategories);
255	}
256	
257	export function sessionInvariantError(entry: TimeTrackerEntry): string | null {
258	  if (entry.segments.some(segment => !Number.isFinite(segment.start) || (segment.end !== null && (!Number.isFinite(segment.end) || segment.end < segment.start)))) return "Invalid interval ordering";
259	  let previousEnd = -Infinity;
260	  for (const [index, segment] of entry.segments.entries()) {
261	    if (segment.start < previousEnd) return "Overlapping intervals";
262	    if (segment.end === null && (entry.done || index !== entry.segments.length - 1)) return "Invalid open interval";
263	    previousEnd = segment.end ?? Infinity;
264	  }
265	  return null;
266	}
267	
268	type EntryUpdate = TimeTrackerEntry[] | ((prev: TimeTrackerEntry[]) => TimeTrackerEntry[]);
269	
270	/** All interactive entry mutations use this account-scoped lock. Expected source
271	 * is captured when the command is submitted, never after waiting for the lock. */
272	export async function commitTimeTrackerEntries(
273	  next: EntryUpdate,
274	  expected: readonly TimeTrackerEntry[],
275	  scope: AccountScope,
276	): Promise<TimeTrackerEntry[]> {
277	  accountScope.assertCurrent(scope);
278	  if (typeof navigator === "undefined" || !navigator.locks?.request) throw new Error("Safe timer writes require Web Locks. Use a supported browser; existing data was preserved.");
279	  const physical = accountScope.physicalKey(TIME_TRACKER_ENTRIES_KEY, scope);
280	  return navigator.locks.request(`xai-tt:${physical}`, () => {
281	    accountScope.assertCurrent(scope);
282	    const raw = localStorage.getItem(physical);
283	    const parsed = raw === null ? [] : safeParse(raw);
284	    if (!Array.isArray(parsed) || !parsed.every(isEntry) || parsed.some(entry => sessionInvariantError(entry))) {
285	      throw new Error("Stored sessions need recovery. Original data was preserved; export it before repairing intervals.");
286	    }
287	    const current = parsed.filter(entry => entry.deleted !== true);
288	    if (JSON.stringify(current) !== JSON.stringify(expected)) throw new Error("Sessions changed in another tab. Review the latest data before trying again.");
289	    const updated = typeof next === "function" ? next(current) : next;
290	    if (updated.some(entry => !isEntry(entry) || sessionInvariantError(entry))) throw new Error("The proposed session has invalid intervals. Original data was preserved.");
291	    const active = updated.filter(isRunningEntry);
292	    if (readTimeTrackerMode() === "single" && active.length > 1 && active.some(entry => !current.some(old => old.id === entry.id && isRunningEntry(old)))) {
293	      throw new Error("Single-task mode already has a running session. End it before starting or resuming another.");
294	    }
295	    if (JSON.stringify(updated) !== JSON.stringify(current)) writeTimeTrackerEntries([...parsed.filter(entry => entry.deleted === true), ...updated], scope);
296	    return updated;
297	  });
298	}
299	
300	export function useTimeTrackerEntries() {
301	  const scope = useRef(accountScope.capture()).current;
302	  const [entries, setEntries] = useState(() => readTimeTrackerEntries(scope));
303	  const value = useRef(entries);
304	  const [error, setError] = useState<string | null>(null);
305	  useEffect(() => {
306	    const refresh = () => {
307	      if (!accountScope.isReady(scope)) return;
308	      try { value.current = readTimeTrackerEntries(scope); setEntries(value.current); }
309	      catch { setError("Session storage could not be read. Existing data was preserved."); }
310	    };
311	    window.addEventListener("storage", refresh);
312	    window.addEventListener(TIME_TRACKER_STORAGE_EVENT, refresh);
313	    return () => { window.removeEventListener("storage", refresh); window.removeEventListener(TIME_TRACKER_STORAGE_EVENT, refresh); };
314	  }, [scope]);
315	  const commit = useCallback(async (next: EntryUpdate): Promise<boolean> => {
316	    const expected = value.current;
317	    try {
318	      await commitTimeTrackerEntries(next, expected, scope);
319	      accountScope.assertCurrent(scope);
320	      value.current = readTimeTrackerEntries(scope); setEntries(value.current); setError(null); return true;
321	    } catch (cause) { setError(cause instanceof Error ? cause.message : "Session could not be saved."); return false; }
322	  }, [scope]);
323	  const exportSource = () => {
324	    accountScope.assertCurrent(scope);
325	    return localStorage.getItem(accountScope.physicalKey(TIME_TRACKER_ENTRIES_KEY, scope)) ?? "[]";
326	  };
327	  return [entries, commit, { error, exportSource }] as const;
328	}
329	
330	export function useTimeTrackerMode(): readonly [TimeTrackerMode, (next: TimeTrackerMode | ((prev: TimeTrackerMode) => TimeTrackerMode)) => void] {
331	  const read = useCallback(readTimeTrackerMode, []);
332	  const write = useCallback(writeTimeTrackerMode, []);
333	  return useTimeTrackerStorage(read, write);
334	}
335	
336	export function useCategoryMap(categories: readonly TimeTrackerCategory[]): ReadonlyMap<string, TimeTrackerCategory> {
337	  return useMemo(() => new Map(categories.map((category) => [category.id, category])), [categories]);
338	}
339	
340	registerAccountMigrationValidator(TIME_TRACKER_CATEGORIES_KEY, value => Array.isArray(value) && value.every(isCategory));
341	registerAccountMigrationValidator(TIME_TRACKER_ENTRIES_KEY, value => Array.isArray(value) && value.every(isEntry));
342

